use std::{fs,path::Path};
fn main(){let dir=std::env::args().nth(1).unwrap();let path=Path::new(&dir);let data=fs::read_to_string(path.join("CONTROL.tsv")).unwrap();let mut out=String::from("g\tchecked\texcluded\tscanned\texceptions\tfibres\ttransitions\tsigned_rank_sum\tclosed_sum\tmin_fibres\tmax_fibres\n");let mut rows=vec![];
for g in 2..=4{let(mut checked,mut excluded,mut scanned,mut exceptions,mut fibres,mut transitions,mut ranks,mut closed,mut lo,mut hi)=(0u64,0u64,0u64,0u64,0u64,0u64,0u64,0u64,u64::MAX,0u64);for line in data.lines().skip(1){let z:Vec<_>=line.split('\t').collect();if z[0].parse::<usize>().unwrap()!=g{continue}if z[3]!="checked"{excluded+=1;continue}checked+=1;let q:Vec<u64>=z[4..].iter().map(|s|s.parse().unwrap()).collect();scanned+=q[0];exceptions+=q[1];fibres+=q[2];transitions+=q[3];ranks+=q[5];closed+=q[6];lo=lo.min(q[2]);hi=hi.max(q[2]);}out+=&format!("{g}\t{checked}\t{excluded}\t{scanned}\t{exceptions}\t{fibres}\t{transitions}\t{ranks}\t{closed}\t{lo}\t{hi}\n");rows.push((g,checked,scanned,fibres,transitions));}
assert!(!path.join("SUMMARY.tsv").exists());fs::write(path.join("SUMMARY.tsv"),&out).unwrap();print!("{out}");let maximum=rows.iter().map(|z|z.2).max().unwrap() as f64;
let mut svg=String::from("<svg xmlns='http://www.w3.org/2000/svg' width='1000' height='510' viewBox='0 0 1000 510'><rect width='1000' height='510' fill='white'/><g font-family='Arial' fill='#172b3a'><text x='45' y='35' font-size='22'>Root-free fibre sweep: exact control counts</text><text x='45' y='62' font-size='15'>Summed across eligible divisors per genus; each pencil is rebuilt independently.</text>");
for (i,(g,n,scanned,fibres,transitions)) in rows.iter().enumerate(){let y=100+i*105;svg+=&format!("<text x='40' y='{}' font-size='16'>g{g} / n={n}</text>",y+18);for (j,(label,value,color)) in [("scanned",*scanned,"#257b83"),("full fibres",*fibres,"#b15f32"),("transitions",*transitions,"#53627c")].iter().enumerate(){let yy=y+j*27;let w=*value as f64/maximum*580.;svg+=&format!("<rect x='175' y='{yy}' width='{w:.2}' height='19' fill='{color}'/><text x='{:.2}' y='{}' font-size='13'>{label}: {value}</text>",185.+w,yy+15);}}
svg+="<text x='45' y='453' font-size='14'>Transitions repeat the same decomposition within a fibre; ranks are not pooled across pencils.</text><text x='45' y='480' font-size='13'>hec_fibre_pencil_20261116 / CONTROL.tsv / exact deterministic counts, no uncertainty or wall timing.</text></g></svg>";fs::write(path.join("COUNTS.svg"),svg).unwrap();}
